    private static void run_case0(Action<bool, string> check)
    {
        string label = "ButtonBase.OnAutoSizeChanged";
        foreach (OverrideMode mode in new[] { OverrideMode.around, OverrideMode.suppress })
        {
            HookLog log = new HookLog();
            using Case0 control = new Case0(log);
            using SubscriptionScope scope = SubscriptionScope.subscribe(control, "auto_size_changed", log);
            write0(control, false);
            log.marks.Clear();
            log.mode = mode;
            write0(control, true);
            string expected = mode == OverrideMode.around ? "BSA" : "B";
            check(log.text == expected, label + " " + mode + ": order " + expected + ", got " + log.text);
            if (mode == OverrideMode.around)
            {
                log.marks.Clear();
                control.raise_directly();
                check(log.text == "BSA", label + " called directly: got " + log.text);
            }
        }
    }

    private static void write0(Case0 control, bool second)
    {
        if (second)
        {
            gf_value value = default;
